+.sidenav {
+    display: none;
+}
+
+.sidenav .sidenav-title {
+    display: block;
+    margin: 0 0 20px;
+    font-family: var(--heading-font-family);
+    font-size: var(--body-font-size-s);
+    font-weight: 700;
+    color: var(--text-color);
+}
+
+.sidenav ul {
+    margin: 0;
+    padding: 0 0 0 12px;
+    list-style: none;
+}
+
+.sidenav > ul {
+    padding-left: 0;
+}
+
+.sidenav li {
+    margin-top: 10px;
+    display: flex;
+    flex-wrap: wrap;
+    align-items: center;
+    gap: 8px;
+}
+
+.sidenav li > a {
+    flex: 1 1 0;
+    color: var(--text-color);
+    text-decoration: none;
+    line-height: 1.4;
+}
+
